/* =====================================================================
   KintiBus_TEST · copia de producción de hoy a las 02:00, con correos y teléfonos enmascarados
   Kinti Bus (cooperativa ficticia) · Mesa de Datos
   Crea la base, sus 8 tablas con sus restricciones y carga los datos.
   Ejecútelo completo en SSMS (F5). Si la base existe, se reemplaza.
   ===================================================================== */
USE master;
GO
IF DB_ID('KintiBus_TEST') IS NOT NULL
BEGIN
    ALTER DATABASE KintiBus_TEST SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE KintiBus_TEST;
END
GO
CREATE DATABASE KintiBus_TEST;
GO
USE KintiBus_TEST;
GO
CREATE TABLE dbo.Terminales (
  TerminalID INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Terminales PRIMARY KEY,
  Nombre NVARCHAR(60) NOT NULL CONSTRAINT UQ_Terminales_Nombre UNIQUE,
  Ciudad NVARCHAR(40) NOT NULL,
  Provincia NVARCHAR(40) NOT NULL
);
GO
CREATE TABLE dbo.Rutas (
  RutaID INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Rutas PRIMARY KEY,
  Codigo VARCHAR(10) NOT NULL CONSTRAINT UQ_Rutas_Codigo UNIQUE,
  OrigenID INT NOT NULL CONSTRAINT FK_Rutas_Origen FOREIGN KEY REFERENCES Terminales(TerminalID),
  DestinoID INT NOT NULL CONSTRAINT FK_Rutas_Destino FOREIGN KEY REFERENCES Terminales(TerminalID),
  DistanciaKm SMALLINT NOT NULL,
  DuracionMin SMALLINT NOT NULL,
  PrecioBase DECIMAL(6,2) NOT NULL CONSTRAINT CK_Rutas_PrecioBase CHECK (PrecioBase > 0),
  Activa BIT NOT NULL CONSTRAINT DF_Rutas_Activa DEFAULT 1
);
GO
CREATE TABLE dbo.Buses (
  BusID INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Buses PRIMARY KEY,
  Placa VARCHAR(8) NOT NULL CONSTRAINT UQ_Buses_Placa UNIQUE,
  Disco SMALLINT NOT NULL CONSTRAINT UQ_Buses_Disco UNIQUE,
  Marca NVARCHAR(30) NOT NULL,
  Modelo NVARCHAR(30) NOT NULL,
  Anio SMALLINT NOT NULL CONSTRAINT CK_Buses_Anio CHECK (Anio BETWEEN 2000 AND 2027),
  Capacidad TINYINT NOT NULL CONSTRAINT CK_Buses_Capacidad CHECK (Capacidad BETWEEN 20 AND 60),
  Estado VARCHAR(15) NOT NULL CONSTRAINT DF_Buses_Estado DEFAULT 'ACTIVO' CONSTRAINT CK_Buses_Estado CHECK (Estado IN ('ACTIVO','MANTENIMIENTO','BAJA'))
);
GO
CREATE TABLE dbo.Conductores (
  ConductorID INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Conductores PRIMARY KEY,
  Cedula VARCHAR(10) NOT NULL CONSTRAINT UQ_Conductores_Cedula UNIQUE,
  Nombres NVARCHAR(40) NOT NULL,
  Apellidos NVARCHAR(40) NOT NULL,
  Licencia CHAR(1) NOT NULL CONSTRAINT CK_Conductores_Licencia CHECK (Licencia IN ('D','E')),
  LicenciaVence DATE NOT NULL,
  Activo BIT NOT NULL CONSTRAINT DF_Conductores_Activo DEFAULT 1
);
GO
CREATE TABLE dbo.Clientes (
  ClienteID INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Clientes PRIMARY KEY,
  Cedula VARCHAR(10) NOT NULL CONSTRAINT UQ_Clientes_Cedula UNIQUE,
  Nombres NVARCHAR(40) NOT NULL,
  Apellidos NVARCHAR(40) NOT NULL,
  Email NVARCHAR(80) NULL,
  Telefono VARCHAR(10) NULL,
  FechaNacimiento DATE NULL,
  Tarifa VARCHAR(15) NOT NULL CONSTRAINT DF_Clientes_Tarifa DEFAULT 'GENERAL' CONSTRAINT CK_Clientes_Tarifa CHECK (Tarifa IN ('GENERAL','TERCERA EDAD','DISCAPACIDAD','MENOR')),
  FechaRegistro DATETIME NOT NULL
);
GO
CREATE TABLE dbo.Viajes (
  ViajeID INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Viajes PRIMARY KEY,
  RutaID INT NOT NULL CONSTRAINT FK_Viajes_Rutas FOREIGN KEY REFERENCES Rutas(RutaID),
  BusID INT NOT NULL CONSTRAINT FK_Viajes_Buses FOREIGN KEY REFERENCES Buses(BusID),
  ConductorID INT NOT NULL CONSTRAINT FK_Viajes_Conductores FOREIGN KEY REFERENCES Conductores(ConductorID),
  Salida DATETIME NOT NULL,
  Estado VARCHAR(12) NOT NULL CONSTRAINT DF_Viajes_Estado DEFAULT 'PROGRAMADO' CONSTRAINT CK_Viajes_Estado CHECK (Estado IN ('PROGRAMADO','EN RUTA','FINALIZADO','CANCELADO'))
);
GO
CREATE TABLE dbo.Boletos (
  BoletoID INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Boletos PRIMARY KEY,
  Codigo VARCHAR(10) NOT NULL CONSTRAINT UQ_Boletos_Codigo UNIQUE,
  ViajeID INT NOT NULL CONSTRAINT FK_Boletos_Viajes FOREIGN KEY REFERENCES Viajes(ViajeID),
  ClienteID INT NOT NULL CONSTRAINT FK_Boletos_Clientes FOREIGN KEY REFERENCES Clientes(ClienteID),
  Asiento TINYINT NOT NULL CONSTRAINT CK_Boletos_Asiento CHECK (Asiento BETWEEN 1 AND 60),
  Precio DECIMAL(6,2) NOT NULL CONSTRAINT CK_Boletos_Precio CHECK (Precio >= 0),
  Descuento DECIMAL(6,2) NOT NULL CONSTRAINT DF_Boletos_Descuento DEFAULT 0,
  Canal VARCHAR(10) NOT NULL CONSTRAINT CK_Boletos_Canal CHECK (Canal IN ('TAQUILLA','WEB','APP')),
  FechaVenta DATETIME NOT NULL,
  Estado VARCHAR(12) NOT NULL CONSTRAINT DF_Boletos_Estado DEFAULT 'VENDIDO' CONSTRAINT CK_Boletos_Estado CHECK (Estado IN ('VENDIDO','USADO','ANULADO','REEMBOLSADO')),
  CONSTRAINT CK_Boletos_Descuento CHECK (Descuento >= 0 AND Descuento <= Precio)
);
GO
CREATE UNIQUE INDEX UX_Boletos_ViajeAsiento ON dbo.Boletos (ViajeID, Asiento) WHERE Estado IN ('VENDIDO','USADO');
GO
CREATE TABLE dbo.Pagos (
  PagoID INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Pagos PRIMARY KEY,
  BoletoID INT NOT NULL CONSTRAINT FK_Pagos_Boletos FOREIGN KEY REFERENCES Boletos(BoletoID),
  Monto DECIMAL(6,2) NOT NULL CONSTRAINT CK_Pagos_Monto CHECK (Monto >= 0),
  Metodo VARCHAR(15) NOT NULL CONSTRAINT CK_Pagos_Metodo CHECK (Metodo IN ('EFECTIVO','TARJETA','TRANSFERENCIA')),
  FechaPago DATETIME NOT NULL,
  Estado VARCHAR(10) NOT NULL CONSTRAINT CK_Pagos_Estado CHECK (Estado IN ('APROBADO','RECHAZADO','DEVUELTO')),
  Referencia VARCHAR(20) NULL
);
GO
SET NOCOUNT ON;
GO
/* Terminales: 12 filas */
SET IDENTITY_INSERT dbo.Terminales ON;
SET IDENTITY_INSERT dbo.Terminales OFF;
GO
/* Rutas: 18 filas */
SET IDENTITY_INSERT dbo.Rutas ON;
SET IDENTITY_INSERT dbo.Rutas OFF;
GO
/* Buses: 24 filas */
SET IDENTITY_INSERT dbo.Buses ON;
SET IDENTITY_INSERT dbo.Buses OFF;
GO
/* Conductores: 30 filas */
SET IDENTITY_INSERT dbo.Conductores ON;
SET IDENTITY_INSERT dbo.Conductores OFF;
GO
/* Clientes: 1183 filas */
SET IDENTITY_INSERT dbo.Clientes ON;
SET IDENTITY_INSERT dbo.Clientes OFF;
GO
/* Viajes: 386 filas */
SET IDENTITY_INSERT dbo.Viajes ON;
SET IDENTITY_INSERT dbo.Viajes OFF;
GO
/* Boletos: 8957 filas */
SET IDENTITY_INSERT dbo.Boletos ON;
SET IDENTITY_INSERT dbo.Boletos OFF;
GO
/* Pagos: 9503 filas */
SET IDENTITY_INSERT dbo.Pagos ON;
SET IDENTITY_INSERT dbo.Pagos OFF;
GO
SET NOCOUNT OFF;
SELECT 'Terminales' AS Tabla, COUNT(*) AS Filas FROM dbo.Terminales UNION ALL SELECT 'Rutas', COUNT(*) FROM dbo.Rutas UNION ALL SELECT 'Buses', COUNT(*) FROM dbo.Buses
UNION ALL SELECT 'Conductores', COUNT(*) FROM dbo.Conductores UNION ALL SELECT 'Clientes', COUNT(*) FROM dbo.Clientes UNION ALL SELECT 'Viajes', COUNT(*) FROM dbo.Viajes
UNION ALL SELECT 'Boletos', COUNT(*) FROM dbo.Boletos UNION ALL SELECT 'Pagos', COUNT(*) FROM dbo.Pagos;
GO
